/**
 * Local data gateway — the whole app with no backend.
 *
 * Site content comes from the bundle snapshot in src/content (regenerated by
 * `node scripts/dump-bundle.mjs`). Bookings, leads, admin edits and the demo
 * session live in localStorage. Rules mirror the SQL layer: first booked wins,
 * a 10-minute hold for requests never sent on WhatsApp, slots start at opening
 * and the last one ends by closing time.
 *
 * Demo login: owner@demo.local / demo1234. This is a UI demo, not security.
 */
import seedJson from "../../content/setapak.bundle.json";
import type {
  AdminBooking,
  AdminFaq,
  AdminInvite,
  AdminLead,
  AdminMember,
  AdminOverview,
  AdminSessionResponse,
  AdminSettings,
  AvailabilityResponse,
  Booking,
  BookingResponse,
  BookingStatus,
  BookingStatusResponse,
  I18nText,
  LeadResponse,
  Offering,
  PlatformOverview,
  ScheduleDay,
  SiteBundle,
  SiteContact,
  SlotDay,
} from "../../types";
import { ApiError } from "../errors";
import type {
  AdminSessionSummary,
  CreateBookingInput,
  CreateLeadInput,
  DataGateway,
} from "./types";

const seed = seedJson as unknown as SiteBundle;
const STORAGE_KEY = "coresite.local.v1";
const DEMO_IDENTIFIER = "owner@demo.local";
const DEMO_PASSWORD = "demo1234";
const KL_OFFSET_MS = 8 * 60 * 60 * 1000;
const HOLD_MINUTES = 10;
const LEAD_MINUTES = 60;

interface LocalBooking {
  id: string;
  ref: string;
  token: string;
  offering_slug: string;
  starts_at: string;
  ends_at: string;
  status: BookingStatus;
  customer_name: string;
  contact_masked: string;
  locale: string;
  amount_cents: number | null;
  deposit_cents: number | null;
  payment_verified: boolean;
  created_at: string;
  whatsapp_sent_at: string | null;
}

interface LocalLead {
  id: string;
  ref: string;
  name: string;
  contact_masked: string;
  message: string;
  status: "new" | "contacted" | "closed";
  locale: string;
  source: string;
  internal_notes: string;
  created_at: string;
}

interface LocalInvite {
  id: string;
  email: string;
  role: string;
  tenant_id: string | null;
  token: string;
  expires_at: string;
  used_at: string | null;
  created_at: string;
}

interface LocalState {
  bookings: LocalBooking[];
  leads: LocalLead[];
  invites: LocalInvite[];
  offeringOverrides: Record<string, Partial<Offering>>;
  settingsOverride: Record<string, unknown> | null;
  session: { staff: { id: string; name: string; role: string }; expires_at: string } | null;
}

const emptyState = (): LocalState => ({
  bookings: [],
  leads: [],
  invites: [],
  offeringOverrides: {},
  settingsOverride: null,
  session: null,
});

let memoryState: string | null = null;

function readRaw(): string | null {
  try {
    return globalThis.localStorage?.getItem(STORAGE_KEY) ?? memoryState;
  } catch {
    return memoryState;
  }
}

function writeRaw(value: string): void {
  memoryState = value;
  try {
    globalThis.localStorage?.setItem(STORAGE_KEY, value);
  } catch {
    // Private mode: keep the in-memory copy only.
  }
}

function loadState(): LocalState {
  const raw = readRaw();
  if (!raw) return emptyState();
  try {
    return { ...emptyState(), ...(JSON.parse(raw) as Partial<LocalState>) };
  } catch {
    return emptyState();
  }
}

function saveState(state: LocalState): void {
  writeRaw(JSON.stringify(state));
}

/** Test hook: drop the in-memory copy so each test starts from the seed. */
export function resetLocalState(): void {
  memoryState = null;
}

// --- time helpers (Malaysia is UTC+8 all year, no DST) -----------------------
function klNowParts(ms: number): { y: number; m: number; d: number } {
  const local = new Date(ms + KL_OFFSET_MS);
  return { y: local.getUTCFullYear(), m: local.getUTCMonth(), d: local.getUTCDate() };
}

function klTimeLabel(ms: number): string {
  const local = new Date(ms + KL_OFFSET_MS);
  return `${String(local.getUTCHours()).padStart(2, "0")}:${String(local.getUTCMinutes()).padStart(2, "0")}`;
}

function hhmmToMinutes(value: string): number {
  const [h, m] = value.split(":").map(Number);
  return h * 60 + m;
}

function minutesToHHMM(total: number): string {
  return `${String(Math.floor(total / 60)).padStart(2, "0")}:${String(total % 60).padStart(2, "0")}`;
}

function localToUtcMs(y: number, m: number, d: number, minutes: number): number {
  return Date.UTC(y, m, d, 0, minutes) - KL_OFFSET_MS;
}

function iso(ms: number): string {
  return new Date(ms).toISOString().replace(".000Z", "Z");
}

// --- small utilities --------------------------------------------------------
function randomHex(length: number): string {
  const bytes = new Uint8Array(Math.ceil(length / 2));
  crypto.getRandomValues(bytes);
  return Array.from(bytes, (b) => b.toString(16).padStart(2, "0")).join("").slice(0, length).toUpperCase();
}

function newId(): string {
  return crypto.randomUUID();
}

function normalizePhone(raw: string): string {
  const digits = (raw ?? "").replace(/\D/g, "");
  return digits.startsWith("0") ? `6${digits}` : digits;
}

function maskPhone(raw: string): string {
  const digits = normalizePhone(raw);
  return digits.length < 7 ? "—" : `${digits.slice(0, 4)}***${digits.slice(-3)}`;
}

function isValidPhone(raw: string): boolean {
  return /^\d{9,15}$/.test(normalizePhone(raw));
}

function pickText(value: I18nText | undefined, locale: string): string {
  if (!value) return "";
  return value[locale] || value.en || "";
}

function offeringBySlug(slug: string): Offering | undefined {
  return seed.offerings.find((item) => item.slug === slug);
}

function offeringById(id: string): Offering | null {
  return seed.offerings.find((item) => item.id === id) ?? null;
}

function durationOf(offering: Offering | undefined): number {
  const minutes = Number(offering?.attributes?.duration_min ?? 45);
  return Math.max(45, Math.min(minutes, 120));
}

function closesAt(): string {
  const contact = (seed.site.contact ?? {}) as SiteContact & { closes_at?: string };
  return contact.closes_at || "23:00";
}

function scheduleFor(weekday: number): ScheduleDay | undefined {
  return seed.schedule.find((day) => day.weekday === weekday);
}

function emptySlotDay(date: string, weekday: number): SlotDay {
  return {
    date,
    weekday,
    weekday_label: weekdayLabel(weekday),
    weekday_name: weekdayLabel(weekday),
    slots: [],
  };
}

function weekdayLabel(weekday: number): I18nText {
  const names = ["Ahad", "Isnin", "Selasa", "Rabu", "Khamis", "Jumaat", "Sabtu"];
  const en = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"];
  const zh = ["周日", "周一", "周二", "周三", "周四", "周五", "周六"];
  return { en: en[weekday], ms: names[weekday], zh: zh[weekday] };
}

function releaseHolds(state: LocalState, nowMs: number): boolean {
  let changed = false;
  for (const booking of state.bookings) {
    if (booking.status !== "pending" || booking.whatsapp_sent_at) continue;
    if (nowMs - Date.parse(booking.created_at) > HOLD_MINUTES * 60_000) {
      booking.status = "cancelled";
      changed = true;
    }
  }
  return changed;
}

function activeBookings(state: LocalState): LocalBooking[] {
  return state.bookings.filter((b) => b.status === "pending" || b.status === "confirmed");
}

function buildDays(state: LocalState, offering: Offering | undefined, days: number, nowMs: number): SlotDay[] {
  const duration = durationOf(offering);
  const step = Math.max(duration, 45);
  const closeMinutes = hhmmToMinutes(closesAt());
  const cutoff = nowMs + LEAD_MINUTES * 60_000;
  const booked = activeBookings(state).map((b) => ({
    start: Date.parse(b.starts_at),
    end: Date.parse(b.ends_at),
  }));
  const today = klNowParts(nowMs);
  const result: SlotDay[] = [];

  for (let offset = 0; offset < days; offset += 1) {
    const localMidnight = Date.UTC(today.y, today.m, today.d + offset);
    const date = new Date(localMidnight).toISOString().slice(0, 10);
    const weekday = new Date(localMidnight).getUTCDay();
    const schedule = scheduleFor(weekday);
    if (!schedule || schedule.closed || !schedule.start) {
      result.push(emptySlotDay(date, weekday));
      continue;
    }
    const startMinutes = hhmmToMinutes(schedule.start);
    const lastStart = closeMinutes - duration;
    const slots: SlotDay["slots"] = [];
    for (let cursor = startMinutes; cursor <= lastStart; cursor += step) {
      const startMs = localToUtcMs(today.y, today.m, today.d + offset, cursor);
      const endMs = startMs + duration * 60_000;
      if (startMs <= cutoff) continue;
      if (booked.some((b) => startMs < b.end && endMs > b.start)) continue;
      slots.push({ starts_at: iso(startMs), time: minutesToHHMM(cursor) });
    }
    result.push({
      date,
      weekday,
      weekday_label: weekdayLabel(weekday),
      weekday_name: weekdayLabel(weekday),
      slots,
    });
  }
  return result;
}

function toBooking(record: LocalBooking, includeToken = true): Booking {
  return {
    ref: record.ref,
    status: record.status,
    starts_at: record.starts_at,
    ends_at: record.ends_at,
    customer_name: record.customer_name,
    customer_contact_masked: record.contact_masked,
    deposit_cents: record.deposit_cents,
    amount_cents: record.amount_cents,
    payment_verified: record.payment_verified,
    locale: record.locale,
    offering: offeringBySlug(record.offering_slug) ?? null,
    ...(includeToken ? { cancel_token: record.token } : {}),
  };
}

function whatsappMessage(
  ref: string,
  offering: Offering | undefined,
  startsAtMs: number,
  name: string,
  phone: string,
  locale: string,
): string {
  const brand = pickText(seed.site.brand_name, locale);
  const service = pickText(offering?.title, locale);
  const local = new Date(startsAtMs + KL_OFFSET_MS);
  const when =
    locale === "zh"
      ? `${local.getUTCFullYear()}年${String(local.getUTCMonth() + 1).padStart(2, "0")}月${String(
          local.getUTCDate(),
        ).padStart(2, "0")}日 ${klTimeLabel(startsAtMs)}`
      : new Date(startsAtMs).toLocaleString("en-MY", {
          timeZone: "Asia/Kuala_Lumpur",
          weekday: "short",
          day: "numeric",
          month: "short",
          year: "numeric",
          hour: "numeric",
          minute: "2-digit",
        });
  if (locale === "zh") {
    return `你好 ${brand}，我想确认预约。\n预约编号：${ref}\n服务：${service}\n时间：${when}\n姓名：${name}\n联络号码：${phone}\n\n请确认这个时段，谢谢。`;
  }
  return `Hi ${brand}, I'd like to confirm this appointment.\nBooking ref: ${ref}\nService: ${service}\nTime: ${when}\nName: ${name}\nPhone: ${phone}\n\nPlease confirm the slot. Thank you.`;
}

function whatsappUrl(record: LocalBooking, phone: string | null): string {
  const number = normalizePhone(String((seed.site.contact as SiteContact).whatsapp ?? ""));
  if (!number) return "";
  const message = whatsappMessage(
    record.ref,
    offeringBySlug(record.offering_slug),
    Date.parse(record.starts_at),
    record.customer_name,
    phone ?? "—",
    record.locale,
  );
  const cleaned = phone ? message : message.replace(/联络号码：—\n/, "").replace(/Phone: —\n/, "");
  return `https://wa.me/${number}?text=${encodeURIComponent(cleaned)}`;
}

function findBooking(state: LocalState, ref: string, token: string): LocalBooking {
  const record = state.bookings.find(
    (item) => item.ref === ref.trim().toUpperCase() && item.token === token,
  );
  if (!record) throw new ApiError("Booking not found", 404, "booking_not_found");
  return record;
}

function requireSession(state: LocalState): NonNullable<LocalState["session"]> {
  if (!state.session || Date.parse(state.session.expires_at) < Date.now()) {
    throw new ApiError("Not signed in", 401, "unauthorized");
  }
  return state.session;
}

function toAdminBooking(record: LocalBooking): AdminBooking {
  return { ...toBooking(record, false), id: record.id, created_at: record.created_at };
}

function toAdminLead(lead: LocalLead): AdminLead {
  return {
    id: lead.id,
    ref: lead.ref,
    name: lead.name,
    contact_masked: lead.contact_masked,
    message: lead.message,
    status: lead.status,
    locale: lead.locale,
    source: lead.source,
    internal_notes: lead.internal_notes,
    created_at: lead.created_at,
  };
}

function adminSettingsFrom(state: LocalState): AdminSettings {
  const site = seed.site;
  const merged = { ...site, ...(state.settingsOverride ?? {}) } as typeof site & {
    theme_preset?: string;
  };
  return {
    brand_name: merged.brand_name,
    contact: merged.contact as SiteContact,
    payment_config: {
      bank_name: String((merged.payment as { bank_name?: string })?.bank_name ?? ""),
      account_number: String((merged.payment as { account_number?: string })?.account_number ?? ""),
      account_holder: String((merged.payment as { account_holder?: string })?.account_holder ?? ""),
      qr_image_url: String((merged.payment as { qr_image_url?: string })?.qr_image_url ?? ""),
      merchant_webhook_url: "",
    },
    labels: merged.labels,
    theme: merged.theme,
    theme_preset: merged.theme.preset ?? merged.theme_preset ?? "slate-mist",
    theme_presets: [
      {
        key: merged.theme.preset ?? "slate-mist",
        label: merged.theme.preset ?? "slate-mist",
        tokens: merged.theme.tokens,
      },
    ],
    default_locale: merged.default_locale,
    locales: merged.locales,
    checkout_mode: merged.checkout_mode,
    booking_mode: merged.booking_mode,
    forwarding_configured: false,
  };
}

export function createLocalGateway(): DataGateway {
  let activeTenant: string | null = null;

  const withState = <T>(fn: (state: LocalState) => T): T => {
    const state = loadState();
    const result = fn(state);
    saveState(state);
    return result;
  };

  return {
    setActiveTenant(slug: string | null): void {
      activeTenant = slug;
    },

    async fetchSite(): Promise<SiteBundle> {
      return { ...seed, tenant: { ...seed.tenant, slug: activeTenant ?? seed.tenant.slug } };
    },

    async fetchAvailability(offeringSlug: string | null, days = 14): Promise<AvailabilityResponse> {
      return withState((state) => {
        releaseHolds(state, Date.now());
        const offering = offeringSlug ? offeringBySlug(offeringSlug) : undefined;
        if (offeringSlug && !offering) {
          throw new ApiError("Service not found", 404, "offering_not_found");
        }
        return {
          timezone: seed.site.timezone,
          days: buildDays(state, offering, Math.max(1, Math.min(days, 30)), Date.now()),
          server_time: iso(Date.now()),
        };
      });
    },

    async createBooking(input: CreateBookingInput): Promise<BookingResponse> {
      return withState((state) => {
        if (input.website) throw new ApiError("Invalid submission", 400, "invalid_submission");
        if (!input.consent) throw new ApiError("Consent is required", 422, "consent_required");
        const name = (input.customer_name ?? "").trim().replace(/\s+/g, " ");
        if (name.length < 2) throw new ApiError("Invalid name", 422, "invalid_name");
        if (!isValidPhone(input.customer_phone)) {
          throw new ApiError("Invalid phone number", 422, "invalid_phone");
        }
        const offering = offeringBySlug(input.offering_slug);
        if (!offering) throw new ApiError("Service not found", 404, "offering_not_found");

        const now = Date.now();
        releaseHolds(state, now);
        const startsMs = Date.parse(input.starts_at);
        const days = buildDays(state, offering, 30, now);
        const matches = days.some((day) =>
          day.slots.some((slot) => Date.parse(slot.starts_at) === startsMs),
        );
        if (!matches) throw new ApiError("That slot is no longer available", 409, "slot_unavailable");

        const duration = durationOf(offering);
        const local = klNowParts(now);
        const yymmdd = `${String(local.y % 100).padStart(2, "0")}${String(local.m + 1).padStart(2, "0")}${String(local.d).padStart(2, "0")}`;
        const ref = `${input.offering_slug.replace(/[^a-z]/gi, "").slice(0, 3).toUpperCase()}-${yymmdd}-${randomHex(4)}`;
        const token = randomHex(32).toLowerCase();
        const record: LocalBooking = {
          id: newId(),
          ref,
          token,
          offering_slug: offering.slug,
          starts_at: iso(startsMs),
          ends_at: iso(startsMs + duration * 60_000),
          status: "pending",
          customer_name: name,
          contact_masked: maskPhone(input.customer_phone),
          locale: ["en", "ms", "zh"].includes(input.locale) ? input.locale : "en",
          amount_cents: offering.price_cents ?? null,
          deposit_cents: offering.deposit_cents ?? null,
          payment_verified: false,
          created_at: iso(now),
          whatsapp_sent_at: null,
        };
        state.bookings.push(record);
        return {
          booking: toBooking(record),
          whatsapp_url: whatsappUrl(record, input.customer_phone),
          forwarded: "not_configured",
          forward_error: null,
        };
      });
    },

    async fetchBooking(ref: string, token: string): Promise<BookingStatusResponse> {
      return withState((state) => {
        releaseHolds(state, Date.now());
        const record = findBooking(state, ref, token);
        return {
          booking: toBooking(record),
          whatsapp_url: whatsappUrl(record, null),
        };
      });
    },

    async cancelBooking(ref: string, token: string): Promise<BookingStatusResponse> {
      return withState((state) => {
        const record = findBooking(state, ref, token);
        if (record.status === "pending" || record.status === "confirmed") {
          record.status = "cancelled";
        } else if (record.status !== "cancelled" && record.status !== "declined") {
          throw new ApiError("This booking cannot be cancelled", 409, "cannot_cancel");
        }
        return { booking: toBooking(record), whatsapp_url: "" };
      });
    },

    async uploadProof(): Promise<{ ok: boolean }> {
      throw new ApiError("Payment proof upload needs a server", 501, "proof_unsupported");
    },

    async createLead(input: CreateLeadInput): Promise<LeadResponse> {
      return withState((state) => {
        if (input.website) throw new ApiError("Invalid submission", 400, "invalid_submission");
        if (!input.consent) throw new ApiError("Consent is required", 422, "consent_required");
        const name = (input.customer_name ?? "").trim().replace(/\s+/g, " ");
        if (name.length < 2) throw new ApiError("Invalid name", 422, "invalid_name");
        if (!isValidPhone(input.customer_phone)) {
          throw new ApiError("Invalid phone number", 422, "invalid_phone");
        }
        const message = (input.message ?? "").trim();
        if (message.length < 5) throw new ApiError("Message is too short", 422, "invalid_message");
        const now = Date.now();
        const local = klNowParts(now);
        const ref = `LED-${String(local.y % 100).padStart(2, "0")}${String(local.m + 1).padStart(2, "0")}${String(local.d).padStart(2, "0")}-${randomHex(4)}`;
        const lead: LocalLead = {
          id: newId(),
          ref,
          name,
          contact_masked: maskPhone(input.customer_phone),
          message,
          status: "new",
          locale: ["en", "ms", "zh"].includes(input.locale) ? input.locale : "en",
          source: "website_contact",
          internal_notes: "",
          created_at: iso(now),
        };
        state.leads.push(lead);
        return { lead: { ref, status: "new" }, whatsapp_url: "" };
      });
    },

    async adminLogin(identifier: string, password: string): Promise<AdminSessionResponse> {
      return withState((state) => {
        const okId = identifier.trim().toLowerCase() === DEMO_IDENTIFIER;
        if (!okId || password !== DEMO_PASSWORD) {
          throw new ApiError("Invalid login", 401, "invalid_credentials");
        }
        const session = {
          staff: { id: "local-demo", name: "Demo Owner", role: "owner" },
          expires_at: new Date(Date.now() + 12 * 3600_000).toISOString(),
        };
        state.session = session;
        return { token: "local-demo", ...session, staff: { ...session.staff, tenant_slug: seed.tenant.slug } };
      });
    },

    async adminLogout(): Promise<{ ok: boolean }> {
      return withState((state) => {
        state.session = null;
        return { ok: true };
      });
    },

    async adminSession(): Promise<AdminSessionSummary> {
      const state = loadState();
      const session = requireSession(state);
      return { staff: session.staff, expires_at: session.expires_at };
    },

    async adminOverview(): Promise<AdminOverview> {
      return withState((state) => {
        requireSession(state);
        releaseHolds(state, Date.now());
        const today = klNowParts(Date.now());
        const dayStart = localToUtcMs(today.y, today.m, today.d, 0);
        const dayEnd = dayStart + 24 * 3600_000;
        const active = activeBookings(state);
        return {
          tenant: { slug: seed.tenant.slug, brand_name: seed.site.brand_name },
          counts: {
            pending_bookings: state.bookings.filter((b) => b.status === "pending").length,
            today_bookings: active.filter(
              (b) => Date.parse(b.starts_at) >= dayStart && Date.parse(b.starts_at) < dayEnd,
            ).length,
            new_leads: state.leads.filter((l) => l.status === "new").length,
            published_offerings: seed.offerings.filter((o) => o.status === "published").length,
          },
          upcoming: active
            .filter((b) => Date.parse(b.starts_at) >= dayStart)
            .sort((a, b) => Date.parse(a.starts_at) - Date.parse(b.starts_at))
            .slice(0, 6)
            .map((b) => toAdminBooking(b)),
          latest_leads: [...state.leads]
            .sort((a, b) => Date.parse(b.created_at) - Date.parse(a.created_at))
            .slice(0, 4)
            .map(toAdminLead),
        };
      });
    },

    async adminBookings(status = "all"): Promise<{ bookings: AdminBooking[] }> {
      return withState((state) => {
        requireSession(state);
        const rows = [...state.bookings]
          .filter((b) => status === "all" || b.status === status)
          .sort((a, b) => Date.parse(b.starts_at) - Date.parse(a.starts_at))
          .map((b) => toAdminBooking(b));
        return { bookings: rows };
      });
    },

    async adminUpdateBooking(
      id: string,
      body: { status?: string; payment_verified?: boolean },
    ): Promise<{ booking: AdminBooking }> {
      return withState((state) => {
        requireSession(state);
        const record = state.bookings.find((b) => b.id === id);
        if (!record) throw new ApiError("Booking not found", 404, "booking_not_found");
        if (body.status) {
          if (!["pending", "confirmed", "declined", "cancelled"].includes(body.status)) {
            throw new ApiError("Invalid status", 422, "invalid_status");
          }
          record.status = body.status as BookingStatus;
        }
        if (typeof body.payment_verified === "boolean") {
          record.payment_verified = body.payment_verified;
        }
        return { booking: toAdminBooking(record) };
      });
    },

    async adminLeads(status = "all"): Promise<{ leads: AdminLead[] }> {
      return withState((state) => {
        requireSession(state);
        return {
          leads: [...state.leads]
            .filter((l) => status === "all" || l.status === status)
            .sort((a, b) => Date.parse(b.created_at) - Date.parse(a.created_at))
            .map(toAdminLead),
        };
      });
    },

    async adminUpdateLead(
      id: string,
      body: { status?: string; internal_notes?: string },
    ): Promise<{ lead: AdminLead }> {
      return withState((state) => {
        requireSession(state);
        const lead = state.leads.find((l) => l.id === id);
        if (!lead) throw new ApiError("Lead not found", 404, "lead_not_found");
        if (body.status) {
          if (!["new", "contacted", "closed"].includes(body.status)) {
            throw new ApiError("Invalid status", 422, "invalid_status");
          }
          lead.status = body.status as LocalLead["status"];
        }
        if (typeof body.internal_notes === "string") lead.internal_notes = body.internal_notes;
        return { lead: toAdminLead(lead) };
      });
    },

    async adminOfferings(): Promise<{ offerings: Offering[] }> {
      return withState((state) => {
        requireSession(state);
        return {
          offerings: seed.offerings.map((item) => ({
            ...item,
            ...(state.offeringOverrides[item.id] ?? {}),
          })),
        };
      });
    },

    async adminUpdateOffering(
      id: string,
      body: Record<string, unknown>,
    ): Promise<{ offering: Offering }> {
      return withState((state) => {
        requireSession(state);
        const base = offeringById(id);
        if (!base) throw new ApiError("Service not found", 404, "offering_not_found");
        state.offeringOverrides[id] = { ...(state.offeringOverrides[id] ?? {}), ...body };
        return { offering: { ...base, ...(state.offeringOverrides[id] ?? {}) } };
      });
    },

    async adminSettings(): Promise<AdminSettings> {
      return withState((state) => {
        requireSession(state);
        return adminSettingsFrom(state);
      });
    },

    async adminUpdateSettings(body: Record<string, unknown>): Promise<AdminSettings> {
      return withState((state) => {
        requireSession(state);
        state.settingsOverride = { ...(state.settingsOverride ?? {}), ...body };
        return adminSettingsFrom(state);
      });
    },

    async adminFaq(): Promise<{ faq: AdminFaq[] }> {
      return withState((state) => {
        requireSession(state);
        return {
          faq: seed.faq.map((item, index) => ({
            id: item.id,
            question: item.question,
            answer: item.answer,
            published: true,
            sort: index,
          })),
        };
      });
    },

    async platformOverview(): Promise<PlatformOverview> {
      return withState((state) => {
        requireSession(state);
        return {
          tenants: [
            {
              id: seed.tenant.id,
              slug: seed.tenant.slug,
              status: seed.tenant.status,
              plan: "starter",
              brand_name: seed.site.brand_name,
              pending_bookings: state.bookings.filter((b) => b.status === "pending").length,
              new_leads: state.leads.filter((l) => l.status === "new").length,
              published_offerings: seed.offerings.filter((o) => o.status === "published").length,
            },
          ],
        };
      });
    },

    async adminCreateInvite(input: {
      email: string;
      role: string;
      tenantId?: string | null;
    }): Promise<AdminInvite> {
      return withState((state) => {
        requireSession(state);
        const email = input.email.trim().toLowerCase();
        if (!email.includes("@")) throw new ApiError("Invalid email", 422, "invalid_email");
        if (!["owner", "manager", "staff", "platform"].includes(input.role)) {
          throw new ApiError("Invalid role", 422, "invalid_role");
        }
        const invite: LocalInvite = {
          id: newId(),
          email,
          role: input.role,
          tenant_id: input.role === "platform" ? null : (input.tenantId ?? seed.tenant.id),
          token: randomHex(64).toLowerCase(),
          expires_at: new Date(Date.now() + 72 * 3600_000).toISOString(),
          used_at: null,
          created_at: iso(Date.now()),
        };
        state.invites.push(invite);
        return {
          id: invite.id,
          email: invite.email,
          role: invite.role,
          tenant_id: invite.tenant_id,
          token: invite.token,
          expires_at: invite.expires_at,
          created_at: invite.created_at,
        };
      });
    },

    async adminListInvites(): Promise<{ invites: AdminInvite[] }> {
      return withState((state) => {
        requireSession(state);
        return {
          invites: [...state.invites]
            .sort((a, b) => Date.parse(b.created_at) - Date.parse(a.created_at))
            .map((invite) => ({
              id: invite.id,
              email: invite.email,
              role: invite.role,
              tenant_id: invite.tenant_id,
              expires_at: invite.expires_at,
              used_at: invite.used_at,
              created_at: invite.created_at,
            })),
        };
      });
    },

    async adminClaimInvite(token: string): Promise<{
      ok: boolean;
      tenant_id: string | null;
      role: string;
    }> {
      return withState((state) => {
        requireSession(state);
        const invite = state.invites.find(
          (item) => item.token === token && !item.used_at && Date.parse(item.expires_at) > Date.now(),
        );
        if (!invite) throw new ApiError("That invite is not valid", 400, "invite_invalid");
        invite.used_at = iso(Date.now());
        return { ok: true, tenant_id: invite.tenant_id, role: invite.role };
      });
    },

    async adminListMembers(): Promise<{ members: AdminMember[] }> {
      return withState((state) => {
        const session = requireSession(state);
        return { members: [{ user_id: session.staff.id, role: session.staff.role, active: true }] };
      });
    },
  };
}
